class Solution {
    public String answerString(String word, int numFriends) {
        if (numFriends == 1) return word;
        int n = word.length();
        int i = 0, j = 1, k = 0;
        while (j + k < n) {
            int d = word.charAt(i + k) - word.charAt(j + k);
            if (d == 0) {
                k++;
            } else if (d < 0) {
                i += k + 1;
                k = 0;
                if (i >= j) j = i + 1;
            } else {
                j += k + 1;
                k = 0;
            }
        }
        String s = word.substring(i);
        int maxLen = n - numFriends + 1;
        return s.substring(0, Math.min(s.length(), maxLen));
    }
}

var answerString = function(word, numFriends) {
    if (numFriends === 1) return word;
    const n = word.length;
    let i = 0, j = 1, k = 0;
    while (j + k < n) {
        const d = word.charCodeAt(i + k) - word.charCodeAt(j + k);
        if (d === 0) {
            k++;
        } else if (d < 0) {
            i += k + 1;
            k = 0;
            if (i >= j) j = i + 1;
        } else {
            j += k + 1;
            k = 0;
        }
    }
    const s = word.slice(i);
    const maxLen = n - numFriends + 1;
    return s.slice(0, Math.min(s.length, maxLen));
};
